// The app's entry point. `app.rs` is generated by nuclo-native-ts; `nuclo` is the runtime's
// backend-independent core (the same files as the GTK target's), and `gpui_backend` draws it
// with GPUI. `native` is the app's own platform code (its native/linux-gpui/ folder), empty
// when it has none.

mod app;
mod gpui_backend;
mod gpui_field;
mod native;
mod nuclo;

fn main() {
    gpui_backend::run(app::nuclo_main);
}
